const motion=document.querySelector('#motion');function updateMotion(){document.body.classList.toggle('motion-paused',paused);motion.setAttribute('aria-pressed',String(paused));motion.innerHTML=paused?'Bật chuyển động <span>▷</span>':'Tạm dừng chuyển động <span>Ⅱ</span>'}updateMotion();motion.onclick=()=>{paused=!paused;updateMotion()};reduce.addEventListener('change',e=>{paused=e.matches;updateMotion()});
