const tabs=[...document.querySelectorAll('[data-layer]')];function selectLayer(i){activeLayer=i;tabs.forEach((t,n)=>{t.setAttribute('aria-selected',String(n===i));t.tabIndex=n===i?0:-1});const panel=document.querySelector('#layer-panel');panel.setAttribute('aria-labelledby',`tab-${i}`);panel.querySelector('h3').innerHTML=layerContent[i][0];panel.querySelector('p').textContent=layerContent[i][1]};tabs.forEach((b,i)=>{b.onclick=()=>selectLayer(i);b.onkeydown=e=>{let n;if(e.key==='ArrowDown')n=(i+1)%4;if(e.key==='ArrowUp')n=(i+3)%4;if(e.key==='Home')n=0;if(e.key==='End')n=3;if(n!==undefined){e.preventDefault();selectLayer(n);tabs[n].focus()}}});
