const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){if(!paused)e.target.classList.add('revealed');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.metrics,.architecture-copy,.section-heading,.pillars article,.project').forEach(e=>observer.observe(e));
function setupCanvas(id){const canvas=document.getElementById(id),ctx=canvas.getContext('2d');let w=0,h=0;const size=()=>{const r=canvas.getBoundingClientRect();if(w===r.width&&h===r.height)return;w=r.width;h=r.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0)};new ResizeObserver(size).observe(canvas);size();return{canvas,ctx,get w(){return w},get h(){return h}}}
const circuit=setupCanvas('circuits'),globe=setupCanvas('globe');let seed=26;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};const lines=Array.from({length:48},(_,i)=>({y:i/48,end:.26+rand()*.46,bend:.05+rand()*.28,speed:.03+rand()*.07,phase:rand(),tone:rand()}));const dots=Array.from({length:90},()=>({x:rand(),y:rand(),r:rand()*1.5+.3,phase:rand()*6}));
function circuitFrame(t){const{ctx:c,w,h}=circuit;c.clearRect(0,0,w,h);const scale=w<720?1.65:1;const glow=c.createRadialGradient(w*.27,h*.43,0,w*.27,h*.43,w*.5);glow.addColorStop(0,'#65142630');glow.addColorStop(1,'#09030500');c.fillStyle=glow;c.fillRect(0,0,w,h);lines.forEach((l,i)=>{const y=100+l.y*(h-170),x0=-20,x1=w*l.bend*scale,x2=x1+38,x3=w*l.end*scale,dy=(i%3-1)*32;const pts=[[x0,y],[x1,y],[x2,y+dy],[x3-45,y+dy],[x3,y+dy-45],[x3+35,y+dy-45]];c.beginPath();pts.forEach(([x,y],j)=>j?c.lineTo(x,y):c.moveTo(x,y));c.strokeStyle=l.tone>.65?'#943d1f66':'#8f173c66';c.lineWidth=i%6===0?1.4:.7;c.stroke();c.fillStyle='#b223435f';c.beginPath();c.arc(x3+35,y+dy-45,2,0,Math.PI*2);c.fill();let lengths=[],total=0;for(let j=1;j<pts.length;j++){const d=Math.hypot(pts[j][0]-pts[j-1][0],pts[j][1]-pts[j-1][1]);lengths.push(d);total+=d}let at=((t*l.speed+l.phase)%1)*total;for(let j=0;j<lengths.length;j++){if(at<=lengths[j]){const p=at/lengths[j],x=pts[j][0]+(pts[j+1][0]-pts[j][0])*p,yy=pts[j][1]+(pts[j+1][1]-pts[j][1])*p;c.fillStyle=i%4?'#ff2456':'#ef7130';c.shadowColor=c.fillStyle;c.shadowBlur=10;c.beginPath();c.arc(x,yy,1.6,0,Math.PI*2);c.fill();c.shadowBlur=0;break}at-=lengths[j]}});dots.forEach(d=>{c.globalAlpha=.3+.25*Math.sin(t+d.phase);c.fillStyle='#df2849';c.beginPath();c.arc(d.x*w*.8,d.y*h,d.r,0,7);c.fill()});c.globalAlpha=1}
const spherePoints=[];for(let a=0;a<23;a++)for(let b=0;b<45;b++){const lat=Math.PI*(a/22-.5),lon=Math.PI*2*b/45;spherePoints.push([Math.cos(lat)*Math.cos(lon),Math.sin(lat),Math.cos(lat)*Math.sin(lon)])}
function globeFrame(t){const{ctx:c,w,h}=globe;c.clearRect(0,0,w,h);const s=Math.min(w/560,h/580),cx=w*.32,cy=h*.49,r=135*s,angle=t*.10;const project=p=>{const x=p[0]*Math.cos(angle)+p[2]*Math.sin(angle),z=-p[0]*Math.sin(angle)+p[2]*Math.cos(angle);return[cx+x*r,cy+p[1]*r,z]};const radial=c.createRadialGradient(cx,cy,0,cx,cy,r*1.5);radial.addColorStop(0,'#72082733');radial.addColorStop(.7,'#a8173422');radial.addColorStop(1,'#ff174400');c.fillStyle=radial;c.fillRect(0,0,w,h);c.lineWidth=.5;for(let a=0;a<23;a++){c.beginPath();for(let b=0;b<=45;b++){const p=project(spherePoints[a*45+b%45]);b?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1])}c.strokeStyle='#c82a4a35';c.stroke()}for(let b=0;b<45;b+=3){c.beginPath();for(let a=0;a<23;a++){const p=project(spherePoints[a*45+b]);a?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1])}c.strokeStyle='#de31583a';c.stroke()}spherePoints.forEach((p,i)=>{const[x,y,z]=project(p);c.globalAlpha=.12+(z+1)*.35;c.fillStyle=i%13===0?'#ffb0c1':'#ff345e';c.beginPath();c.arc(x,y,(i%13===0?1.6:.7)*s,0,7);c.fill()});c.globalAlpha=1;c.strokeStyle='#ff335760';c.beginPath();c.arc(cx,cy,r+10*s,0,7);c.stroke();const sx=w*.66,sw=105*s,sh=37*s;for(let i=3;i>=0;i--){const y=h*.24+i*92*s+Math.sin(t*.6+i*.8)*4*s,selected=i===activeLayer;c.beginPath();c.moveTo(sx-sw,y);c.lineTo(sx,y-sh);c.lineTo(sx+sw,y);c.lineTo(sx,y+sh);c.closePath();c.fillStyle=selected?'#a725454a':'#4c162633';c.fill();c.strokeStyle=selected?'#ff7593':'#b73151';c.lineWidth=selected?1.5:1;c.shadowColor='#ff214e';c.shadowBlur=selected?14:3;c.stroke();c.shadowBlur=0;c.beginPath();c.moveTo(sx-sw,y);c.lineTo(sx-sw,y+10*s);c.lineTo(sx,y+sh+10*s);c.lineTo(sx+sw,y+10*s);c.lineTo(sx+sw,y);c.moveTo(sx,y+sh);c.lineTo(sx,y+sh+10*s);c.strokeStyle='#a32b46';c.stroke();for(let j=-3;j<=3;j++){c.beginPath();c.moveTo(sx+j*23*s,y-sh+Math.abs(j)*8*s);c.lineTo(sx+j*23*s,y+sh-Math.abs(j)*8*s);c.strokeStyle='#e6466628';c.stroke()}c.fillStyle=selected?'#ffc5d3':'#aa6072';c.font=`${9*s}px monospace`;c.fillText(['GOVERNANCE','MANAGEMENT','EXECUTION','SERVICE'][i],sx-40*s,y+4*s);if(i<3){c.setLineDash([2,5]);[-sw,0,sw].forEach(dx=>{c.beginPath();c.moveTo(sx+dx,y+12*s);c.lineTo(sx+dx,y+85*s);c.strokeStyle='#fa446440';c.stroke()});c.setLineDash([])}}c.beginPath();c.moveTo(cx+r*.6,cy);c.lineTo(sx-sw-20*s,cy);c.lineTo(sx-sw-20*s,h*.24+activeLayer*92*s);c.lineTo(sx-sw,h*.24+activeLayer*92*s);c.strokeStyle='#ff32577a';c.lineWidth=1;c.stroke()}
let time=0,last=0,cacheCircuit='',cacheGlobe='';function animate(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!document.hidden){if(!paused)time+=dt;const hr=circuit.canvas.getBoundingClientRect(),gr=globe.canvas.getBoundingClientRect();const ck=`${circuit.w}:${circuit.h}:${time}`,gk=`${globe.w}:${globe.h}:${time}:${activeLayer}`;if(!cacheCircuit||(hr.bottom>0&&hr.top<innerHeight&&ck!==cacheCircuit)){circuitFrame(time);cacheCircuit=ck}if(!cacheGlobe||(gr.bottom>0&&gr.top<innerHeight&&gk!==cacheGlobe)){globeFrame(time);cacheGlobe=gk}}requestAnimationFrame(animate)}requestAnimationFrame(animate);


